Popover.example:
import { Popover, PopoverContent } from '@carbon/react';
import React from 'react';

function CustomComponent() {
  const [open, setOpen] = React.useState(false);

  return (
    <Popover open={open}>
      <button
        type="button"
        onClick={() => {
          setOpen(!open);
        }}>
        Toggle
      </button>
      <PopoverContent>
        The content that is revealed by interacting with the Toggle button
      </PopoverContent>
    </Popover>
  );
}

