function SynchronizedTreeView() {
  const [selected, setSelected] = useState([]);
  const [active, setActive] = useState(null);

  return (
    <FeatureFlags enableTreeViewControllable>
      <TreeView
        selected={selected}
        onSelect={setSelected}
        active={active}
        onActivate={setActive}>
        ...
      </TreeView>
    </FeatureFlags>
  );
}
